import json
TOOLS = {
  "search_poi": {"required": {"query": str}, "optional": {"near": str, "category": str}},
  "set_destination": {"required": {"poi_id": str}, "optional": {"via": list}},
}
def check(call):
    t = TOOLS.get(call["name"])
    if t is None: return "없는 도구"
    args = call["arguments"]
    for k, typ in t["required"].items():
        if k not in args: return f"빠진 인자 {k}"
        if not isinstance(args[k], typ): return f"타입 틀림 {k}"
    extra = set(args) - set(t["required"]) - set(t["optional"])
    return f"모르는 인자 {sorted(extra)}" if extra else "OK"

for o in ['{"name": "search_poi", "arguments": {"query": "성심당", "near": "대전역"}}',
          '{"name": "search_poi", "arguments": {"near": "대전역"}}',
          '{"name": "set_destination", "arguments": {"poi_id": "P123", "speed": "fast"}}',
          '{"name": "call_taxi", "arguments": {}}',
          '{"name": "search_poi", "arguments": {"query": "주유소"']:
    try: print(check(json.loads(o)))
    except json.JSONDecodeError: print("JSON 깨짐")
# OK / 빠진 인자 query / 모르는 인자 ['speed'] / 없는 도구 / JSON 깨짐
